  1	package hotel;
  2	
  3	import hotel.messages.EmailSender;
  4	import hotel.messages.SentMessages;
  5	import hotel.reports.OccupancyReport;
  6	import hotel.reports.RatePlanReport;
  7	import hotel.reports.RevenueReport;
  8	import hotel.reports.TourismTaxReport;
  9	import hotel.reservations.PriceCalculator;
 10	import hotel.reservations.ReservationService;
 11	import hotel.reservations.ReservationStore;
 12	import hotel.rooms.Rooms;
 13	import hotel.web.HttpApi;
 14	import io.javalin.Javalin;
 15	
 16	/** Puts the inn's pieces together and runs the HTTP server. */
 17	public final class Hotel {
 18	
 19	    private final Javalin server;
 20	
 21	    public Hotel() {
 22	        Rooms rooms = new Rooms();
 23	        ReservationStore store = new ReservationStore();
 24	        SentMessages sentMessages = new SentMessages();
 25	        ReservationService reservations =
 26	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
 27	        HttpApi api = new HttpApi(
 28	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store),
 29	                new TourismTaxReport(store), new RatePlanReport(store));
 30	        this.server = api.server();
 31	    }
 32	
 33	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
 34	    public int start(int port) {
 35	        server.start(port);
 36	        return server.port();
 37	    }
 38	
 39	    public void stop() {
 40	        server.stop();
 41	    }
 42	
 43	    public static void main(String[] args) {
 44	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 45	        new Hotel().start(port);
 46	    }
 47	}
 48	package hotel.web;
 49	
 50	import com.fasterxml.jackson.databind.ObjectMapper;
 51	import com.fasterxml.jackson.databind.SerializationFeature;
 52	import com.fasterxml.jackson.databind.json.JsonMapper;
 53	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 54	import hotel.messages.SentMessages;
 55	import hotel.reports.OccupancyReport;
 56	import hotel.reports.RatePlanReport;
 57	import hotel.reports.RevenueReport;
 58	import hotel.reports.TourismTaxReport;
 59	import hotel.reservations.ErrorCode;
 60	import hotel.reservations.Guest;
 61	import hotel.reservations.HotelException;
 62	import hotel.reservations.NewReservation;
 63	import hotel.reservations.ReservationService;
 64	import hotel.rooms.Rooms;
 65	import io.javalin.Javalin;
 66	import io.javalin.http.Context;
 67	import io.javalin.json.JavalinJackson;
 68	import java.time.LocalDate;
 69	import java.time.YearMonth;
 70	import java.time.format.DateTimeParseException;
 71	
 72	/** The HTTP API the inn's website and front desk call. */
 73	public final class HttpApi {
 74	
 75	    private final Javalin server;
 76	    private final Rooms rooms;
 77	    private final ReservationService reservations;
 78	    private final SentMessages sentMessages;
 79	    private final OccupancyReport occupancyReport;
 80	    private final RevenueReport revenueReport;
 81	    private final TourismTaxReport tourismTaxReport;
 82	    private final RatePlanReport ratePlanReport;
 83	
 84	    public HttpApi(
 85	            Rooms rooms,
 86	            ReservationService reservations,
 87	            SentMessages sentMessages,
 88	            OccupancyReport occupancyReport,
 89	            RevenueReport revenueReport,
 90	            TourismTaxReport tourismTaxReport,
 91	            RatePlanReport ratePlanReport) {
 92	        this.rooms = rooms;
 93	        this.reservations = reservations;
 94	        this.sentMessages = sentMessages;
 95	        this.occupancyReport = occupancyReport;
 96	        this.revenueReport = revenueReport;
 97	        this.tourismTaxReport = tourismTaxReport;
 98	        this.ratePlanReport = ratePlanReport;
 99	
100	        ObjectMapper jsonMapper = JsonMapper.builder()
101	                .addModule(new JavaTimeModule())
102	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
103	                .build();
104	        this.server = Javalin.create(config -> {
105	            config.showJavalinBanner = false;
106	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
107	        });
108	        registerRoutes();
109	        registerErrorHandling();
110	    }
111	
112	    public Javalin server() {
113	        return server;
114	    }
115	
116	    private void registerRoutes() {
117	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
118	
