312	/**
313	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
314	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
315	 * (half-even) at every step.
316	 */
317	public final class PriceCalculator {
318	
319	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
320	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
321	
322	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
323	        int nights = 0;
324	        BigDecimal subtotal = cents(BigDecimal.ZERO);
325	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
326	            subtotal = subtotal.add(nightPrice(room, night));
327	            nights++;
328	        }
329	        BigDecimal discount = switch (ratePlan) {
330	            case STANDARD -> cents(BigDecimal.ZERO);
331	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
332	        };
333	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
334	    }
335	
336	    BigDecimal nightPrice(Room room, LocalDate night) {
337	        BigDecimal nightlyRate = room.nightlyRate();
338	        if (isHighSeason(night)) {
339	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
340	        }
341	        return cents(nightlyRate);
342	    }
343	
344	    /** High season: from December 15 to the end of February, and the whole of July. */
345	    static boolean isHighSeason(LocalDate date) {
346	        Month month = date.getMonth();
347	        return month == Month.JANUARY
348	                || month == Month.FEBRUARY
349	                || month == Month.JULY
350	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
351	    }
352	
353	    static BigDecimal cents(BigDecimal value) {
354	        return value.setScale(2, RoundingMode.HALF_EVEN);
355	    }
356	}
