   291	        text.append(title).append(" nº ").append(reservationId).append('\n');
   292	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
   293	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
   294	        text.append("Entrada: ").append(TextFormat.date(checkIn))
